CREATE TABLE IF NOT EXISTS plans (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(40) NOT NULL, max_projects INT NOT NULL, max_members INT NOT NULL);
INSERT IGNORE INTO plans (id,name,max_projects,max_members) VALUES (1,'free',5,10),(2,'pro',100,1000);
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, password_hash VARCHAR(100) NOT NULL, failed_attempts INT NOT NULL DEFAULT 0, locked_until DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS organizations (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, slug VARCHAR(60) NOT NULL UNIQUE, plan_id INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (plan_id) REFERENCES plans(id));
CREATE TABLE IF NOT EXISTS memberships (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, user_id BIGINT NOT NULL, role ENUM('owner','admin','member','viewer') NOT NULL, UNIQUE KEY uq_org_user (organization_id,user_id), FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, archived TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_org (organization_id,archived), FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS board_columns (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, project_id BIGINT NOT NULL, name VARCHAR(60) NOT NULL, position DOUBLE NOT NULL, INDEX ix_org_proj (organization_id,project_id), FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, project_id BIGINT NOT NULL, column_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium', assignee_id BIGINT NULL, due_date DATE NULL, position DOUBLE NOT NULL, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_org_proj_col (organization_id,project_id,column_id,position), FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY (column_id) REFERENCES board_columns(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invites (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, email VARCHAR(255) NOT NULL, role ENUM('admin','member','viewer') NOT NULL, token_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, accepted_at DATETIME NULL, UNIQUE KEY uq_token (token_hash), INDEX ix_org (organization_id), FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS comments (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, task_id BIGINT NOT NULL, user_id BIGINT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_org_task (organization_id,task_id), FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, organization_id BIGINT NOT NULL, user_id BIGINT NOT NULL, action VARCHAR(160) NOT NULL, entity VARCHAR(40), entity_id BIGINT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_org_id (organization_id,id), INDEX ix_org_user (organization_id,user_id), FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS refresh_tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS password_resets (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
